function aiActionHtml(a,index=-1){const d=a.data||{},name=({create_transaction:'ثبت تراکنش',edit_transaction:'ویرایش تراکنش',delete_transaction:'حذف تراکنش',create_person:'ساخت شخص',create_project:'ساخت پروژه',pay_installment:'پرداخت قسط',settle_debt:'تسویه بدهی/طلب'})[a.action]||'اقدام',bits=[];if(d.type)bits.push(typeFa(d.type));if(d.amount!==undefined&&d.amount!==null&&d.amount!=='')bits.push(`${fa(Number(d.amount||0))} ${String(d.currency||'IRR').toUpperCase()==='TOMAN'?'تومان':'ریال'}`);if(d.fee_amount)bits.push(`کارمزد ${fa(Number(d.fee_amount))} ${String(d.currency||'IRR').toUpperCase()==='TOMAN'?'تومان':'ریال'}`);if(d.transaction_date)bits.push(d.transaction_date);if(d.transaction_time)bits.push(d.transaction_time);if(d.description)bits.push(d.description);if(d.name||d.title)bits.push(d.name||d.title);if(d.transaction_id)bits.push(`تراکنش ${String(d.transaction_id).slice(0,8)}`);return `<div class="row"><div><b>${esc(name)}</b><span class="muted" style="display:block">${esc(bits.join(' • '))}</span></div>${index>=0?`<button class="danger aiRemove" data-index="${index}">حذف از پیشنهاد</button>`:''}</div>`}
async function aiUi(){
  let caps;try{caps=await api('/api/ai/capabilities',{timeoutMs:12000})}catch(e){caps={text:false,vision:false,audio:false,file:false,error:e.message}}const history=[];
  modal('دستیار مالی',`<div class="ai-shell"><div class="ai-capabilities"><span class="badge ${caps.text?'good':'warn'}">متن ${caps.text?'✓':'×'}</span><span class="badge ${caps.vision?'good':'warn'}">تصویر ${caps.vision?'✓':'×'}</span><span class="badge ${caps.audio?'good':'warn'}">صوت ${caps.audio?'✓':'×'}</span><span class="badge ${caps.file?'good':'warn'}">فایل ${caps.file?'✓':'×'}</span></div>${caps.error?`<p class="danger-text">${esc(caps.error)}</p>`:''}<div id="aiThread" class="ai-thread"><div class="ai-message bot">سلام 👋 می‌تونی طبیعی حرف بزنی؛ مثلاً «دیروز چی خوردم؟» یا «امروز ساعت ۴، صد هزار تومان خرید کردم». برای تغییر مالی همیشه اول پیشنهاد می‌دم.</div></div><div class="ai-composer"><textarea id="aiText"></textarea><div class="ai-hint">Enter ارسال • Shift+Enter خط جدید</div><button id="aiSend" class="primary wide">ارسال</button></div></div>`);
  const th=$('#aiThread'),input=$('#aiText'),send=$('#aiSend'),append=(html)=>{th.insertAdjacentHTML('beforeend',html);th.scrollTop=th.scrollHeight},pushHistory=(user,assistant)=>{history.push({role:'user',content:user},{role:'assistant',content:assistant});while(history.length>12)history.shift()};
  function proposalBody(draftId,actions){return `<div class="list section aiActionList">${actions.map((a,i)=>aiActionHtml(a,i)).join('')||'<div class="muted">اقدامی باقی نمانده است.</div>'}</div><label>اصلاح پیشنهاد<textarea class="aiRevision"></textarea></label><div class="actions"><button class="primary aiConfirm">تأیید همه</button><button class="secondary aiRevise">ویرایش با دستور</button><button class="danger aiCancel">لغو همه</button></div><div class="muted aiProposalStatus"></div>`}
  function bindProposal(card,draftId,actions){card.querySelectorAll('.aiRemove').forEach(b=>b.onclick=async()=>{setBusy(b,true,'حذف…');try{const r=await api(`/api/ai/remove/${draftId}/${b.dataset.index}`,{method:'POST'});if(!r.actions?.length){card.innerHTML='<div class="muted">همه اقدام‌های پیشنهادی حذف شدند.</div>';return}card.innerHTML=`<b>${fa(r.actions.length)} اقدام پیشنهادی</b>${proposalBody(draftId,r.actions)}`;bindProposal(card,draftId,r.actions)}catch(e){card.querySelector('.aiProposalStatus').textContent=e.message;setBusy(b,false)}});card.querySelector('.aiRevise')?.addEventListener('click',async e=>{const instruction=card.querySelector('.aiRevision').value.trim();if(!instruction){card.querySelector('.aiProposalStatus').textContent='اول بنویس چه چیزی باید اصلاح شود.';return}const b=e.currentTarget;setBusy(b,true,'در حال اصلاح…');try{const r=await api(`/api/ai/revise/${draftId}`,{method:'POST',body:{instruction,history},timeoutMs:35000});if(r.kind==='clarify'){card.querySelector('.aiProposalStatus').textContent=r.text||'یک توضیح بیشتر لازم است.';setBusy(b,false);return}card.innerHTML=`<b>پیشنهاد اصلاح شد</b>${proposalBody(draftId,r.actions||[])}`;bindProposal(card,draftId,r.actions||[])}catch(err){card.querySelector('.aiProposalStatus').textContent=err.message;setBusy(b,false)}});card.querySelector('.aiConfirm')?.addEventListener('click',async e=>{const b=e.currentTarget;setBusy(b,true,'در حال ثبت…');card.querySelector('.aiProposalStatus').textContent='در حال اجرای اقدام‌های تأییدشده…';try{const r=await api(`/api/ai/confirm/${draftId}`,{method:'POST',timeoutMs:50000});card.innerHTML=`<div class="positive">✅ ${fa(r.items?.length||actions.length)} اقدام انجام شد.</div>`;invalidateMaps()}catch(err){card.querySelector('.aiProposalStatus').textContent='ثبت انجام نشد: '+err.message;setBusy(b,false)}});card.querySelector('.aiCancel')?.addEventListener('click',async e=>{const b=e.currentTarget;setBusy(b,true,'لغو…');try{await api(`/api/ai/cancel/${draftId}`,{method:'POST'});card.innerHTML='<div class="muted">پیشنهاد لغو شد.</div>'}catch(err){card.querySelector('.aiProposalStatus').textContent=err.message;setBusy(b,false)}})}
  async function sendMessage(){const text=input.value.trim();if(!text)return;append(`<div class="ai-message user">${esc(text)}</div>`);input.value='';setBusy(send,true,'در حال فکر کردن…');const thinking=document.createElement('div');thinking.className='ai-message bot thinking';thinking.textContent='🤖 دارم بررسی می‌کنم…';th.append(thinking);th.scrollTop=th.scrollHeight;try{const r=await api('/api/ai/ask',{method:'POST',body:{text,history},timeoutMs:35000});thinking.remove();let assistant='';if(r.kind==='actions'){assistant=`${fa(r.actions.length)} اقدام پیشنهادی آماده شد.`;const card=document.createElement('div');card.className='ai-proposal';card.innerHTML=`<b>${assistant}</b>${proposalBody(r.draft_id,r.actions)}`;th.append(card);bindProposal(card,r.draft_id,r.actions)}else if(r.kind==='split'){assistant='محاسبه دنگ انجام شد.';append(`<div class="ai-message bot">${r.result.settlements.map(x=>`${esc(x.from.name)} ← ${esc(x.to.name)}: ${money(x.amount)}`).join('<br>')||'تسویه‌ای لازم نیست.'}</div>`)}else{assistant=r.text||'';append(`<div class="ai-message bot">${esc(assistant)}</div>`)}pushHistory(text,assistant);th.scrollTop=th.scrollHeight}catch(e){thinking.remove();append(`<div class="ai-message bot danger-text">${esc(e.message)}</div>`)}finally{setBusy(send,false);input.focus()}}
  send.onclick=sendMessage;input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});
}
