  const r=await api('/api/trash'),entityLabel={accounts:'حساب',categories:'دسته',people:'شخص',projects:'پروژه',tags:'برچسب',merchants:'فروشنده',rules:'قانون',templates:'قالب',installments:'قسط',debts:'بدهی/طلب',recurring:'تکرارشونده',budgets:'بودجه'};
