  $('#modalBody').querySelectorAll('.restoreTrash').forEach(b=>b.onclick=async()=>{try{if(b.dataset.kind==='transaction')await api(`/api/transactions/${b.dataset.id}/restore`,{method:'POST'});else await api(`/api/entities/${b.dataset.name}/${b.dataset.id}/undelete`,{method:'POST'});invalidateMaps();toast('بازگردانی شد.');trashUi()}catch(e){toast(e.message)}});
