async function printTransactions(title,rows){const sum=summarizeClient(rows);return printReport(title,{from:'',to:'',summary:sum,transactions:rows,categories:[],breakdowns:{}},{})}
function summarizeClient(rows=[]){let expense=0,income=0,fees=0,refunds=0,inflow=0,outflow=0,transfers=0;for(const t of rows){const a=Number(t.amount||0),f=Number(t.fee_amount||0);fees+=f;if(['expense','installment_payment'].includes(t.type)){expense+=a;outflow+=a+f}else if(t.type==='income'){income+=a;inflow+=a}else if(t.type==='refund'){refunds+=a;inflow+=a;outflow+=f}else if(t.type==='transfer'){transfers+=a;outflow+=f}}const net_expense=expense-refunds;return{count:rows.length,income,expense,net_expense,fees,refunds,net:income-net_expense-fees,inflow,outflow,transfers}}
async function printReport(title,r,filters={}){try{await Promise.all([loadScriptOnce('https://cdn.jsdelivr.net/npm/html2pdf.js@0.10.2/dist/html2pdf.bundle.min.js','html2pdf'),entityMaps()]);const acc=mapBy(S.maps.accounts,'account_id'),cat=mapBy(S.maps.categories,'category_id'),people=mapBy(S.maps.people,'person_id'),projects=mapBy(S.maps.projects,'project_id'),merchants=mapBy(S.maps.merchants,'merchant_id'),sum=r.summary||summarizeClient(r.transactions||[]),host=document.createElement('div'),cell='border:1px solid #d8dee8;padding:6px;vertical-align:top;word-break:break-word';host.dir='rtl';host.style.cssText='font-family:Tahoma,Arial,sans-serif;direction:rtl;padding:24px;background:white;color:#111;width:760px;font-size:10px';host.innerHTML=`<h1 style="font-size:20px;margin:0 0 8px">${esc(title)}</h1><p style="font-size:10px;color:#555">واحد: ${currencyLabel()} ${r.from?`• بازه ${esc(r.from)} تا ${esc(r.to)}`:''} • ساخته‌شده ${esc(tehranIso())}</p><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:14px 0">${[['تعداد',fa(sum.count||0)],['درآمد',money(sum.income)],['خرج خالص',money(sum.net_expense)],['خالص',money(sum.net)],['کارمزد',money(sum.fees)],['بازپرداخت',money(sum.refunds)],['ورودی',money(sum.inflow)],['خروجی',money(sum.outflow)]].map(([k,v])=>`<div style="border:1px solid #d8dee8;border-radius:8px;padding:8px"><small style="color:#666">${k}</small><b style="display:block;margin-top:3px">${v}</b></div>`).join('')}</div><table style="width:100%;border-collapse:collapse;table-layout:fixed"><thead><tr><th style="${cell};width:13%">تاریخ/ساعت</th><th style="${cell};width:9%">نوع</th><th style="${cell};width:12%">مبلغ</th><th style="${cell};width:10%">کارمزد</th><th style="${cell};width:13%">حساب</th><th style="${cell};width:13%">دسته/شخص</th><th style="${cell};width:30%">شرح و جزئیات</th></tr></thead><tbody>${(r.transactions||[]).map(t=>`<tr><td style="${cell}">${esc(t.transaction_date||t.transaction_date_iso||'')}<br>${esc(t.transaction_time||'00:00:00')}</td><td style="${cell}">${esc(typeFa(t.type))}</td><td style="${cell}">${money(t.amount)}</td><td style="${cell}">${money(t.fee_amount||0)}</td><td style="${cell}">${esc(acc[t.account_id]||'—')}${t.destination_account_id?`<br>← ${esc(acc[t.destination_account_id]||'—')}`:''}</td><td style="${cell}">${esc(cat[t.category_id]||'—')}${t.person_id?`<br>${esc(people[t.person_id]||'')}`:''}</td><td style="${cell}">${esc(t.description||'')}${t.project_id?`<br>پروژه: ${esc(projects[t.project_id]||'')}`:''}${t.merchant_id?`<br>فروشنده: ${esc(merchants[t.merchant_id]||'')}`:''}${t.tracking_number?`<br>پیگیری: ${esc(t.tracking_number)}`:''}</td></tr>`).join('')}</tbody></table>`;document.body.append(host);const worker=window.html2pdf().set({margin:7,filename:'finance-report.pdf',pagebreak:{mode:['css','legacy']},html2canvas:{scale:1.35,useCORS:true,logging:false},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(host).toPdf(),pdf=await worker.get('pdf'),blob=pdf.output('blob');host.remove();await sendBlobToChat(blob,`finance-report-${tehranIso()}.pdf`,`${title} — ${fa(sum.count||0)} تراکنش`)}catch(e){document.querySelectorAll('body > div[dir="rtl"][style*="width:760px"]').forEach(x=>x.remove());toast('ساخت یا ارسال PDF انجام نشد: '+e.message)}}
function loadScriptOnce(src,globalName){if(globalName&&window[globalName])return Promise.resolve();return new Promise((res,rej)=>{const old=[...document.scripts].find(x=>x.src===src);if(old){old.addEventListener('load',res,{once:true});old.addEventListener('error',rej,{once:true});return}const s=document.createElement('script');s.src=src;s.onload=res;s.onerror=()=>rej(new Error('کتابخانه خروجی بارگذاری نشد.'));document.head.append(s)})}

